<script>
function copyInviteLink(){const e=document.getElementById('inviteLink');if(!e)return;navigator.clipboard?navigator.clipboard.writeText(e.value):document.execCommand('copy');alert('Link undangan berhasil disalin.');}
(function(){
const c=document.getElementById('countdown');
if(!c)return;
const t=Number(c.dataset.timestamp||0);
if(!Number.isFinite(t)||t<=0){console.warn('Countdown: tanggal acara tidak valid.');return;}
const days=document.getElementById('cdDays');
const hours=document.getElementById('cdHours');
const minutes=document.getElementById('cdMinutes');
const seconds=document.getElementById('cdSeconds');
let timer=null;
function setValue(el,value){if(el)el.textContent=String(value).padStart(2,'0');}
function updateCountdown(){
    const distance=t-Date.now();
    if(distance<=0){
        setValue(days,0);setValue(hours,0);setValue(minutes,0);setValue(seconds,0);
        c.classList.add('is-finished');
        if(timer)clearInterval(timer);
        return;
    }
    setValue(days,Math.floor(distance/86400000));
    setValue(hours,Math.floor((distance%86400000)/3600000));
    setValue(minutes,Math.floor((distance%3600000)/60000));
    setValue(seconds,Math.floor((distance%60000)/1000));
}
updateCountdown();
timer=setInterval(updateCountdown,1000);
})();
(function(){const cover=document.getElementById('cover'),open=document.getElementById('openInvitation'),audio=document.getElementById('bgMusic'),btn=document.getElementById('musicToggle');function playing(){if(btn){btn.classList.add('is-playing');btn.innerHTML='<i class="bi bi-pause-fill"></i>'}}function paused(){if(btn){btn.classList.remove('is-playing');btn.innerHTML='<i class="bi bi-music-note-beamed"></i>'}}if(open)open.addEventListener('click',()=>{cover.classList.add('hide');document.body.style.overflow='';if(audio)audio.play().then(playing).catch(paused)});if(btn&&audio)btn.addEventListener('click',()=>audio.paused?audio.play().then(playing):audio.pause());if(audio)audio.addEventListener('pause',paused)})();
const io=new IntersectionObserver(es=>es.forEach(e=>{if(e.isIntersecting)e.target.classList.add('show')}),{threshold:.12});document.querySelectorAll('.reveal').forEach(e=>io.observe(e));
</script>
</body></html>
